import { CommonModule } from '@angular/common';
import { Component, inject } from '@angular/core';

// --- UI IMPORTS (Atoms & Molecules) ---
import { UiCardComponent } from '../../components/atoms/card/card.component';
import { UiButtonComponent } from '../../components/atoms/button/button.component';
import { UiInputComponent } from '../../components/atoms/input/input.component';
import { TransactionItemComponent } from '../../components/molecules/transaction-item/transaction-item.component';

// --- LOGIC IMPORT (Service) ---
import { BudgetService } from '../../services/budget.service';
import { UiTagComponent } from '../../components/atoms/tag/tag.component';

@Component({
  selector: 'app-home',
  standalone: true,
  imports: [CommonModule,
    UiCardComponent, 
    UiButtonComponent, 
    UiTagComponent,
    UiInputComponent, 
    TransactionItemComponent
  ],
  templateUrl: './home.component.html',
  styleUrl: './home.component.scss',
})
export class HomeComponent {
  // --- DEPENDENCY INJECTION ---
  // Accessing the Singleton Service to get state & methods
  private budgetService = inject(BudgetService);

  // 2. LECTURE DES DONNÉES (SIGNALS)
  transactions = this.budgetService.expenses;
  remainingBudget = this.budgetService.remainingBudget;

  // 3. ÉTAT LOCAL DU FORMULAIRE
  formTitle: string = '';
  formAmount: number | null = null;

  constructor() {
    // Juste pour vérifier que le composant charge bien
    console.log('🏗️ HomeComponent initialisé.');
  }

  /**
   * ÉTAPE 1 : L'utilisateur tape dans le champ TITRE
   * Déclenché par (input) ou (change) dans le HTML
   */
  onTitleChange(event: Event): void {
    console.log('--- 1. Événement onTitleChange détecté ---');

    // a. Récupération de l'élément HTML qui a déclenché l'événement
    const inputElement = event.target as HTMLInputElement;
    console.log('   📍 Élément cible:', inputElement);

    // b. Extraction de la valeur brute
    const newValue = inputElement.value;
    console.log(`   📝 Valeur tapée : "${newValue}"`);

    // c. Mise à jour de la variable de classe (IMPORTANT !)
    this.formTitle = newValue;
    console.log('   💾 Variable this.formTitle mise à jour :', this.formTitle);
  }

  /**
   * ÉTAPE 2 : L'utilisateur tape dans le champ MONTANT
   */
  onAmountChange(event: Event): void {
    console.log('--- 2. Événement onAmountChange détecté ---');

    const inputElement = event.target as HTMLInputElement;
    const rawValue = inputElement.value;
    console.log(`   📝 Valeur brute (string) : "${rawValue}"`);

    // Conversion en nombre (le + ou Number() transforme "10" en 10)
    const newAmount = Number(rawValue);
    console.log(`   🔢 Valeur convertie (number) : ${newAmount}`);

    // Mise à jour de la variable de classe
    this.formAmount = newAmount;
    console.log('   💾 Variable this.formAmount mise à jour :', this.formAmount);
  }

  /**
   * ÉTAPE 3 : L'utilisateur clique sur AJOUTER
   */
  addTransaction() {
    console.log('--- 3. Tentative d\'ajout de transaction ---');
    console.log('   🔎 État actuel du formulaire :', { 
      titre: this.formTitle, 
      montant: this.formAmount 
    });

    // Validation simple
    if (!this.formTitle || !this.formAmount) {
      console.warn('   ⚠️ ERREUR : Le titre ou le montant est vide. Action annulée.');
      return; // On arrête tout ici si c'est vide
    }

    console.log('   ✅ Validation OK. Appel du BudgetService...');

    // Appel au Service (Le Cerveau)
    this.budgetService.addExpense(
      this.formTitle,
      this.formAmount,
      'EMOTIONAL', 
      'Envie'
    );

    console.log('   🚀 Transaction envoyée au service !');

    // Reset du Formulaire (Nettoyage)
    this.formTitle = '';
    this.formAmount = null;
    console.log('   🧹 Formulaire réinitialisé.');
  }

}

