  }

  &--full {
    width: 100%;
  }

  /* Tailles affinées pour éviter l'effet "trop gros" */
  &--sm { height: 34px; padding: 0 14px; font-size: 10px; }
  &--md { height: 42px; padding: 0 20px; font-size: 11px; }
  &--lg { height: 48px; padding: 0 24px; font-size: 12px; }

  /* --- Variantes Solid (Tes couleurs d'origine) --- */

  &--primary {
    background: var(--color-primary);
    color: var(--color-white);
    &:hover:not(:disabled) { transform: translateY(-1px); box-shadow: var(--shadow-sm); }
  }

  &--secondary {
    background: var(--color-secondary);
    color: var(--color-white);
    &:hover:not(:disabled) { transform: translateY(-1px); box-shadow: var(--shadow-sm); }
  }

  &--emotional {
    background: var(--color-emotional);
    color: var(--color-black); // Meilleur contraste sur le rose
    &:hover:not(:disabled) { transform: translateY(-1px); box-shadow: var(--shadow-sm); }
  }

  &--insight {
    background: var(--color-insight);
    color: var(--color-black); // Meilleur contraste sur le jaune
    &:hover:not(:disabled) { transform: translateY(-1px); box-shadow: var(--shadow-sm); }
  }

  &--brown {
    background: var(--color-brown);
    color: var(--color-white);
    &:hover:not(:disabled) { transform: translateY(-1px); box-shadow: var(--shadow-sm); }
  }

