  &--ghost {
    background: #F2F2F2; 
    color: #475467;      
    border: 1px solid rgba(16, 24, 40, 0.1);

    &:hover:not(:disabled) {
      background: #EAEAEA;
      border-color: rgba(16, 24, 40, 0.2);
