/* * ROOT CONTAINER
 * Stacks label, input field, and helper text vertically.
 * Handles the global disabled state opacity.
 */
.ui-input {
  display: flex;
  flex-direction: column;
  gap: 8px; /* Consistent spacing with UiSelect */
  width: 100%;
  opacity: 1;
  transition: opacity 0.2s ease-in-out;

  /* State: Disabled */
  &.is-disabled {
    opacity: 0.6;
    pointer-events: none; /* Prevents user interaction */

    .ui-input__field {
      background-color: #F2F4F7; /* Neutral Grey */
      border-color: #EAECF0;
    }
  }
}

/* * LABEL
 * Uppercase & Bold, consistent with BalanceMe typography.
 * Uses a subtle grey to avoid visual clutter.
 */
.ui-input__label {
  font-family: var(--font-family-base, sans-serif);
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #9CA3AF; /* Cool Grey */
  margin-left: 12px; /* Aligned with the field padding */
}

/* * FIELD WRAPPER
 * The rounded container (Pill shape).
 * Height: 48px (Matches UiSelect for consistency).
 */
.ui-input__field {
  display: flex;
  align-items: center;
  gap: 12px;

  width: 100%;
  height: 48px; /* Standardized height */
  padding: 0 20px;

  border-radius: 999px; /* Full Pill Shape */
  border: 1px solid transparent; /* Prevents layout shift on focus */

  /* --- DEFAULT COLORS --- */
  background-color: #F9FAFB; /* Very light grey */
  border-color: #E5E7EB;     /* Subtle border */

  transition: all 0.2s ease;

  /* Focus State */
  &:focus-within {
    background-color: #FFFFFF;
    border-color: var(--color-primary, #4FA6A6); 
    box-shadow: 0 0 0 4px rgba(79, 166, 166, 0.15); /* Soft teal halo */
  }

  /* Error State (Powder Pink style) */
  &.ui-input__field--error {
    background-color: #FFF1F2; /* Powder Pink */
    border-color: #FDA4AF;     /* Soft Rose */

    &:focus-within {
      border-color: var(--color-emotional, #F43F5E);
      box-shadow: 0 0 0 4px rgba(253, 164, 175, 0.25);
    }
  }
}

/* * NATIVE INPUT CONTROL
 * Invisible styling to blend perfectly into the wrapper.
 */
.ui-input__control {
  width: 100%;
  height: 100%;
  border: none;
  outline: none;
  background: transparent;

  font-family: var(--font-family-base, sans-serif);
  font-size: 15px; /* Legible standard size */
  font-weight: 600;
  color: #374151; /* Dark Grey text */

  /* Placeholder Style */
  &::placeholder {
    color: #D1D5DB; 
    font-weight: 500;
  }
}

/* * ERROR MESSAGE
 * Displayed below the field using the emotional color.
 */
.ui-input__error {
  font-size: 12px;
  color: var(--color-emotional, #9F1239); /* Deep Rose */
  margin-left: 16px;
  margin-top: 4px;
  font-weight: 500;
}

/* * HINT TEXT
 * Helper text below the field.
 */
.ui-input__hint {
  font-size: 12px;
  color: #6B7280;
  margin-left: 16px;
  margin-top: 4px;
}

/* * UTILITY: REMOVE SPINNERS
 * Hides the up/down arrows on number inputs for a cleaner UI.
 */
.ui-input__control[type='number'] {
  -moz-appearance: textfield; /* Firefox */
  appearance: textfield;

  &::-webkit-outer-spin-button,
  &::-webkit-inner-spin-button {
    -webkit-appearance: none; /* Webkit */
    margin: 0;
  }
}

