/* Global Container */
.ui-select {
  display: flex;
  flex-direction: column;
  gap: 8px; /* Airy spacing */
  width: 100%;
  position: relative;
  opacity: 1;
  transition: opacity 0.2s;

  /* Global Disabled State */
  &.is-disabled {
    opacity: 0.6;
    pointer-events: none;

    .ui-select__native {
      background-color: #F2F4F7; /* Neutral Grey */
      border-color: #EAECF0;
      color: #98A2B3;
    }
  }
}

/* Label: BalanceMe Style using Design System Token */
.ui-select__label {
  font-family: var(--font-family-base, sans-serif);
  font-size: 11px; /* Legible size */
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  /* Using the emotional color token instead of hardcoded red */
  color: var(--color-emotional, #D48C9D); 
  margin-left: 12px;
}

/* Relative Wrapper */
.ui-select__control {
  position: relative;
  width: 100%;
  height: 48px; /* Restored comfortable standard height */
}

/* Native Select */
.ui-select__native {
  appearance: none;
  -webkit-appearance: none;
  width: 100%;
  height: 100%;
  padding: 0 40px 0 20px; /* Generous padding */

  border-radius: 999px; /* Pill shape (Full rounding) */
  border: 1px solid transparent;

  font-family: var(--font-family-base, sans-serif);
  font-size: 15px;
  font-weight: 600;
  line-height: 48px; /* Text centering */

  /* --- COLORS --- */
  background-color: #FFF5F7; /* Powder Pink Background */
  border-color: #FCE7EB;     /* Soft Rose Border */
  color: #344054;            /* Dark Grey Text (Legible) */

  cursor: pointer;
  transition: all 0.2s ease;

  &:focus {
    outline: none;
    /* Focus ring using emotional color */
    border-color: var(--color-emotional, #F472B6); 
    box-shadow: 0 0 0 4px rgba(244, 114, 182, 0.15); /* Pink Halo */
    background-color: #FFFFFF;
  }

  /* Placeholder (Empty value) */
  &.placeholder-shown {
    color: #98A2B3; /* Light Grey */
    font-weight: 500;
  }
}

/* --- ERROR VARIANT: POWDER PINK (Softness over Alert) --- */
.ui-select.is-error {
  .ui-select__label { 
    /* Label stays linked to emotional color */
    color: var(--color-emotional, #9F1239); 
  }

  .ui-select__native {
    border-color: #FDA4AF;     /* Soft Rose Border */
    background-color: #FFF1F2; /* Powder Pink Background */
    color: #9F1239;            /* Deep Rose Text (Not bright red) */

    &:focus {
      border-color: var(--color-emotional, #F43F5E);
      box-shadow: 0 0 0 4px rgba(253, 164, 175, 0.25);
    }
  }
}

/* Error Message */
.ui-select__error-msg {
  font-size: 12px;
  /* Deep Rose for legibility, softer than alert red */
  color: #9F1239; 
  margin-left: 16px;
  margin-top: 4px;
  font-weight: 500;
}

/* Chevron SVG */
.ui-select__chevron {
  position: absolute;
  right: 20px; /* Positioned to match pill shape */
  top: 50%;
  transform: translateY(-50%);
  width: 18px;
  height: 18px;
  pointer-events: none;
  /* Chevron takes the Design System color */
  color: var(--color-emotional, #D48C9D); 
  opacity: 0.7;
}

